content.css:
.constraint-sankey-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  display: flex;
  flex-direction: row;
}
.constraint-sankey-root svg {
  shape-rendering: geometricPrecision;
  flex: 1 1 auto;
  min-width: 0;
}
/* ── Nodes ── */
.cs-node {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1;
}
.cs-node:hover {
  filter: brightness(1.12);
  stroke-width: 2;
}
.cs-node-label {
  fill: #333;
  font-size: 11px;
  font-weight: 600;
  pointer-events: none;
}
.cs-node-value {
  fill: #777;
  font-size: 9px;
  pointer-events: none;
}
/* ── Links ── */
.cs-link {
  fill: none;
  cursor: pointer;
  transition: opacity 0.15s ease;
}
.cs-link:hover {
  opacity: 0.6 !important;
}
.cs-link.dimmed {
  opacity: 0.08 !important;
}
/* ── Legend ── */
.cs-legend {
  font-size: 11px;
  fill: #555;
}
/* ── Landing page ── */
.cs-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #888;
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
/* ── Empty data message (cross-filter to zero) ── */
.cs-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #94a3b8;
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Insight Panel ── */
.cs-insight-panel {
  display: none;
  width: 200px;
  min-width: 200px;
  flex: 0 0 200px;
  border-left: 1px solid #e0e0e0;
  background: rgba(255, 255, 255, 0.95);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 12px;
  box-sizing: border-box;
  font-size: 11px;
  color: #333;
}
.cs-insight-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #4682b4;
  margin-bottom: 12px;
  padding-bottom: 6px;
  border-bottom: 2px solid #4682b4;
}
.cs-insight-section {
  margin-bottom: 10px;
}
.cs-insight-label {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #888;
  margin-bottom: 3px;
}
.cs-insight-value {
  font-size: 13px;
  font-weight: 600;
  color: #222;
  word-break: break-word;
}
.cs-insight-bar-row {
  display: flex;
  align-items: center;
  margin-bottom: 4px;
  gap: 6px;
}
.cs-insight-bar-name {
  font-size: 10px;
  color: #555;
  width: 70px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex-shrink: 0;
}
.cs-insight-bar-track {
  flex: 1;
  height: 8px;
  background: #e8e8e8;
  border-radius: 4px;
  overflow: hidden;
}
.cs-insight-bar-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.3s ease;
}
.cs-insight-bar-pct {
  font-size: 9px;
  color: #888;
  width: 32px;
  text-align: right;
  flex-shrink: 0;
}
/* ── Insight Panel child styles ── */
.cs-insight-title {
  font-weight: 700;
  font-size: 13px;
  color: #333;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 2px solid #E8612A;
}
.cs-insight-row {
  display: flex;
  justify-content: space-between;
  padding: 3px 0;
}
.cs-insight-label {
  color: #666;
}
.cs-insight-value {
  font-weight: 600;
  color: #333;
}
.cs-insight-dist {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid #e0e0e0;
}
.cs-insight-dist-title {
  font-weight: 600;
  color: #333;
  margin-bottom: 6px;
}
.cs-insight-dist-item {
  margin-bottom: 4px;
}
.cs-insight-dist-name {
  font-size: 10px;
  color: #666;
  margin-bottom: 1px;
}
.cs-insight-dist-track {
  height: 8px;
  background: #e0e0e0;
  border-radius: 4px;
  overflow: hidden;
}
.cs-insight-dist-fill {
  height: 100%;
  background: linear-gradient(90deg, #4682b4, #27ae60);
  border-radius: 4px;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
